import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Plus, Pencil, Trash2, Search, X, DollarSign, Check, ArrowUpDown, RefreshCw, Star } from 'lucide-react';
import { currencyAPI } from '../services/api';
import { toast } from 'react-toastify';

const Currencies = () => {
  const [currencies, setCurrencies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editing, setEditing] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [form, setForm] = useState({ code: '', name: '', symbol: '', exchangeRate: '1', isBase: false });
  const [errors, setErrors] = useState({});

  const loadData = async () => {
    setLoading(true);
    try {
      const res = await currencyAPI.getAll();
      setCurrencies(Array.isArray(res.data) ? res.data : []);
    } catch { /* ignore */ }
    finally { setLoading(false); }
  };

  useEffect(() => { loadData(); }, []);

  const filtered = currencies.filter(c =>
    c.code?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    c.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
    c.symbol?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleChange = (field) => (e) => {
    const val = e.target.type === 'checkbox' ? e.target.checked : e.target.value;
    setForm({ ...form, [field]: val });
    if (errors[field]) setErrors({ ...errors, [field]: '' });
  };

  const validate = () => {
    const e = {};
    if (!form.code.trim()) e.code = 'Currency code is required';
    else if (!/^[A-Z]{3}$/i.test(form.code.trim())) e.code = 'Code must be 3 letters (e.g. USD)';
    if (!form.name.trim()) e.name = 'Currency name is required';
    if (!form.symbol.trim()) e.symbol = 'Symbol is required';
    if (form.exchangeRate && (isNaN(form.exchangeRate) || parseFloat(form.exchangeRate) < 0)) e.exchangeRate = 'Invalid exchange rate';
    return e;
  };

  const handleSave = async () => {
    const v = validate();
    setErrors(v);
    if (Object.keys(v).length > 0) return;
    try {
      const payload = {
        code: form.code.toUpperCase().trim(),
        name: form.name.trim(),
        symbol: form.symbol.trim(),
        exchangeRate: parseFloat(form.exchangeRate) || 1,
        isBase: form.isBase,
      };
      if (editing) {
        await currencyAPI.update(editing._id, payload);
        toast.success('Currency updated');
      } else {
        await currencyAPI.create(payload);
        toast.success('Currency created');
      }
      setShowModal(false);
      setEditing(null);
      setForm({ code: '', name: '', symbol: '', exchangeRate: '1', isBase: false });
      setErrors({});
      await loadData();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to save currency');
    }
  };

  const handleEdit = (c) => {
    setEditing(c);
    setForm({
      code: c.code || '',
      name: c.name || '',
      symbol: c.symbol || '',
      exchangeRate: String(c.exchangeRate || 1),
      isBase: c.isBase || false,
    });
    setShowModal(true);
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Deactivate this currency?')) return;
    try {
      await currencyAPI.delete(id);
      toast.success('Currency deactivated');
      await loadData();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to delete currency');
    }
  };

  const handleToggleActive = async (c) => {
    try {
      await currencyAPI.update(c._id, { isActive: !c.isActive });
      toast.success(c.isActive ? 'Currency deactivated' : 'Currency activated');
      await loadData();
    } catch (err) {
      toast.error('Failed to update status');
    }
  };

  const openAddModal = () => {
    setEditing(null);
    setForm({ code: '', name: '', symbol: '', exchangeRate: '1', isBase: false });
    setErrors({});
    setShowModal(true);
  };

  const baseCurrency = currencies.find(c => c.isBase);

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-[#0F172A] p-4 md:p-6">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Multi-Currency</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
              Manage currencies and exchange rates for your business
            </p>
          </div>
          <button
            onClick={openAddModal}
            className="flex items-center gap-2 px-4 py-2.5 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
          >
            <Plus size={18} />
            Add Currency
          </button>
        </div>

        {/* Search */}
        <div className="bg-white dark:bg-[#1E293B] rounded-xl border border-gray-200 dark:border-gray-700 p-4 mb-4">
          <div className="relative">
            <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
            <input
              type="text"
              placeholder="Search currencies by code, name, or symbol..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 bg-gray-50 dark:bg-[#0F172A] border border-gray-200 dark:border-gray-700 rounded-lg text-sm text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            {searchQuery && (
              <button onClick={() => setSearchQuery('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                <X size={16} />
              </button>
            )}
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-4">
          <div className="bg-white dark:bg-[#1E293B] rounded-xl border border-gray-200 dark:border-gray-700 p-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center">
                <DollarSign size={20} className="text-blue-600 dark:text-blue-400" />
              </div>
              <div>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">{currencies.length}</p>
                <p className="text-xs text-gray-500 dark:text-gray-400">Total Currencies</p>
              </div>
            </div>
          </div>
          <div className="bg-white dark:bg-[#1E293B] rounded-xl border border-gray-200 dark:border-gray-700 p-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-green-100 dark:bg-green-900/30 flex items-center justify-center">
                <Check size={20} className="text-green-600 dark:text-green-400" />
              </div>
              <div>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">{currencies.filter(c => c.isActive).length}</p>
                <p className="text-xs text-gray-500 dark:text-gray-400">Active Currencies</p>
              </div>
            </div>
          </div>
          <div className="bg-white dark:bg-[#1E293B] rounded-xl border border-gray-200 dark:border-gray-700 p-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-purple-100 dark:bg-purple-900/30 flex items-center justify-center">
                <Star size={20} className="text-purple-600 dark:text-purple-400" />
              </div>
              <div>
                <p className="text-2xl font-bold text-gray-900 dark:text-white">{baseCurrency?.code || 'INR'}</p>
                <p className="text-xs text-gray-500 dark:text-gray-400">Base Currency</p>
              </div>
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white dark:bg-[#1E293B] rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden">
          {loading ? (
            <div className="flex items-center justify-center py-20">
              <RefreshCw size={24} className="animate-spin text-blue-600" />
            </div>
          ) : filtered.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20">
              <DollarSign size={48} className="text-gray-300 dark:text-gray-600 mb-4" />
              <p className="text-gray-500 dark:text-gray-400 text-sm">No currencies found</p>
              <button onClick={openAddModal} className="mt-4 text-blue-600 hover:text-blue-700 text-sm font-medium">
                Add your first currency
              </button>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-gray-200 dark:border-gray-700">
                    <th className="text-left px-6 py-4 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Code</th>
                    <th className="text-left px-6 py-4 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Name</th>
                    <th className="text-left px-6 py-4 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Symbol</th>
                    <th className="text-left px-6 py-4 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Exchange Rate</th>
                    <th className="text-left px-6 py-4 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Status</th>
                    <th className="text-right px-6 py-4 text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-gray-800">
                  {filtered.map((c) => (
                    <tr key={c._id} className="hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors">
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2">
                          <span className="font-mono font-bold text-gray-900 dark:text-white">{c.code}</span>
                          {c.isBase && (
                            <span className="px-2 py-0.5 text-[10px] font-semibold bg-purple-100 dark:bg-purple-900/30 text-purple-700 dark:text-purple-400 rounded-full">
                              BASE
                            </span>
                          )}
                        </div>
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-700 dark:text-gray-300">{c.name}</td>
                      <td className="px-6 py-4 text-lg font-semibold text-gray-900 dark:text-white">{c.symbol}</td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-1">
                          <ArrowUpDown size={14} className="text-gray-400" />
                          <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{c.exchangeRate}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <button
                          onClick={() => handleToggleActive(c)}
                          className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                            c.isActive ? 'bg-green-600' : 'bg-gray-300 dark:bg-gray-600'
                          }`}
                        >
                          <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                            c.isActive ? 'translate-x-6' : 'translate-x-1'
                          }`} />
                        </button>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center justify-end gap-2">
                          <button
                            onClick={() => handleEdit(c)}
                            className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors"
                            title="Edit"
                          >
                            <Pencil size={16} />
                          </button>
                          {!c.isBase && (
                            <button
                              onClick={() => handleDelete(c._id)}
                              className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                              title="Deactivate"
                            >
                              <Trash2 size={16} />
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      {/* Modal */}
      <AnimatePresence>
        {showModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4"
            onClick={() => setShowModal(false)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              className="bg-white dark:bg-[#1E293B] rounded-2xl w-full max-w-md shadow-2xl"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200 dark:border-gray-700">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                  {editing ? 'Edit Currency' : 'Add Currency'}
                </h3>
                <button onClick={() => setShowModal(false)} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg">
                  <X size={20} className="text-gray-500" />
                </button>
              </div>
              <div className="p-6 space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Currency Code *</label>
                  <input
                    type="text"
                    value={form.code}
                    onChange={handleChange('code')}
                    placeholder="e.g. USD"
                    maxLength={3}
                    className={`w-full px-4 py-2.5 bg-gray-50 dark:bg-[#0F172A] border ${errors.code ? 'border-red-500' : 'border-gray-200 dark:border-gray-700'} rounded-lg text-sm text-gray-900 dark:text-white uppercase focus:outline-none focus:ring-2 focus:ring-blue-500`}
                  />
                  {errors.code && <p className="text-red-500 text-xs mt-1">{errors.code}</p>}
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Currency Name *</label>
                  <input
                    type="text"
                    value={form.name}
                    onChange={handleChange('name')}
                    placeholder="e.g. US Dollar"
                    className={`w-full px-4 py-2.5 bg-gray-50 dark:bg-[#0F172A] border ${errors.name ? 'border-red-500' : 'border-gray-200 dark:border-gray-700'} rounded-lg text-sm text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500`}
                  />
                  {errors.name && <p className="text-red-500 text-xs mt-1">{errors.name}</p>}
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Symbol *</label>
                  <input
                    type="text"
                    value={form.symbol}
                    onChange={handleChange('symbol')}
                    placeholder="e.g. $"
                    className={`w-full px-4 py-2.5 bg-gray-50 dark:bg-[#0F172A] border ${errors.symbol ? 'border-red-500' : 'border-gray-200 dark:border-gray-700'} rounded-lg text-sm text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500`}
                  />
                  {errors.symbol && <p className="text-red-500 text-xs mt-1">{errors.symbol}</p>}
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Exchange Rate (to INR) *</label>
                  <input
                    type="number"
                    step="0.000001"
                    min="0"
                    value={form.exchangeRate}
                    onChange={handleChange('exchangeRate')}
                    placeholder="1"
                    className={`w-full px-4 py-2.5 bg-gray-50 dark:bg-[#0F172A] border ${errors.exchangeRate ? 'border-red-500' : 'border-gray-200 dark:border-gray-700'} rounded-lg text-sm text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500`}
                  />
                  {errors.exchangeRate && <p className="text-red-500 text-xs mt-1">{errors.exchangeRate}</p>}
                </div>
                <div className="flex items-center gap-3 py-2">
                  <label className="relative inline-flex items-center cursor-pointer">
                    <input
                      type="checkbox"
                      checked={form.isBase}
                      onChange={handleChange('isBase')}
                      className="sr-only peer"
                    />
                    <div className="w-11 h-6 bg-gray-200 dark:bg-gray-700 peer-focus:ring-2 peer-focus:ring-blue-500 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                  </label>
                  <span className="text-sm text-gray-700 dark:text-gray-300">Set as base currency</span>
                </div>
              </div>
              <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-gray-200 dark:border-gray-700">
                <button
                  onClick={() => setShowModal(false)}
                  className="px-4 py-2 text-sm font-medium text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSave}
                  className="px-4 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors"
                >
                  {editing ? 'Update' : 'Create'}
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Currencies;
